SELECT event, COUNT(*) AS `count` FROM bluesky GROUP BY JSON_VALUE(data, '$.commit.collection') AS event ORDER BY `count` DESC;
SELECT event, COUNT(*) AS `count`, COUNT(DISTINCT JSON_VALUE(data, '$.did')) AS users FROM bluesky WHERE JSON_VALUE(data, '$.kind') = 'commit' AND JSON_VALUE(data, '$.commit.operation') = 'create' GROUP BY JSON_VALUE(data, '$.commit.collection') AS event ORDER BY `count` DESC;
SELECT event, hour_of_day, COUNT(*) AS `count` FROM bluesky WHERE JSON_VALUE(data, '$.kind') = 'commit' AND JSON_VALUE(data, '$.commit.operation') = 'create' AND JSON_VALUE(data, '$.commit.collection') IN ('app.bsky.feed.post', 'app.bsky.feed.repost', 'app.bsky.feed.like') GROUP BY JSON_VALUE(data, '$.commit.collection') AS event, DateTime::GetHour(DateTime::FromMicroseconds(JSON_VALUE(data, '$.time_us' RETURNING Uint64))) AS hour_of_day ORDER BY hour_of_day, event;
SELECT user_id, MIN(DateTime::FromMicroseconds(JSON_VALUE(data, '$.time_us' RETURNING Uint64))) AS first_post_ts FROM bluesky WHERE JSON_VALUE(data, '$.kind') = 'commit' AND JSON_VALUE(data, '$.commit.operation') = 'create' AND JSON_VALUE(data, '$.commit.collection') = 'app.bsky.feed.post' GROUP BY JSON_VALUE(data, '$.did') AS user_id ORDER BY first_post_ts ASC LIMIT 3;
SELECT user_id, DateTime::ToMilliseconds(MAX(DateTime::FromMicroseconds(JSON_VALUE(data, '$.time_us' RETURNING Uint64))) - MIN(DateTime::FromMicroseconds(JSON_VALUE(data, '$.time_us' RETURNING Uint64)))) AS activity_span FROM bluesky WHERE JSON_VALUE(data, '$.kind') = 'commit' AND JSON_VALUE(data, '$.commit.operation') = 'create' AND JSON_VALUE(data, '$.commit.collection') = 'app.bsky.feed.post' GROUP BY JSON_VALUE(data, '$.did') AS user_id ORDER BY activity_span DESC LIMIT 3;
